const architectureCatalog = [
  {id:'arch-linear',title:'Linear Regression',family:'Linear & Factor Models',desc:'Models a continuous target as an affine combination of input features.',formula:'ŷ=wᵀx+b',example:'x=[2,3], w=[0.5,−1], b=2 → ŷ=1−3+2=0.',components:['Numerical/categorical features','Affine layer','Identity output'],tasks:['task-regression','task-forecasting','task-scoring'],diagram:'linear',tradeoff:'Fast and interpretable, but cannot express nonlinear interactions unless they are supplied as features.'},
  {id:'arch-logistic',title:'Logistic Regression',family:'Linear & Factor Models',desc:'Applies a sigmoid to an affine score for binary probability estimation; multinomial logistic regression uses a softmax over several affine logits.',formula:'p=σ(wᵀx+b)',example:'x=[2,1], w=[0.7,−0.4], b=0.1 → z=1.1 → p=0.750.',components:['Affine logit','Sigmoid or multiclass softmax output'],tasks:['task-binary','task-multiclass','task-scoring'],diagram:'linear',tradeoff:'A strong, calibration-friendly baseline—not automatically calibrated. It remains linear in the supplied representation and crosses.'},
  {id:'arch-matrix-factorization',title:'Matrix Factorization',family:'Linear & Factor Models',desc:'Represents users and items with learned latent-factor rows whose dot product predicts affinity.',formula:'r̂ᵤᵢ=μ+bᵤ+bᵢ+pᵤᵀqᵢ',example:'pᵤ=[0.3,0.9], qᵢ=[0.1,0.8] → pᵤᵀqᵢ=0.75 before biases.',components:['User embedding table','Item embedding table','Dot product','Bias terms'],tasks:['task-embedding','task-retrieval'],diagram:'towers',tradeoff:'Strong collaborative baseline, but unseen users/items have no learned row without a fallback.'},
  {id:'arch-tree',title:'Decision Tree',family:'Tree Models',desc:'Recursively partitions feature space with threshold decisions and predicts within each leaf.',formula:'f(x)=Σₗ cₗ·1[x∈Rₗ]',example:'If age<25 go left; otherwise if prior_clicks>3 go right. A user age 30 with 5 clicks lands in the high-CTR leaf.',components:['Split feature','Threshold','Branches','Leaf prediction'],tasks:['task-binary','task-regression'],diagram:'tree',tradeoff:'Interpretable nonlinear rules, but a single tree is unstable and easily overfits.'},
  {id:'arch-gbdt',title:'Gradient-Boosted Trees',family:'Tree Models',desc:'Builds an additive model by fitting each new tree to current loss gradients or residuals.',formula:'Fₘ(x)=Fₘ₋₁(x)+ηhₘ(x)',example:'Current prediction 0.40, new tree output 0.30, η=0.1 → updated prediction 0.43.',components:['Sequence of trees','Gradient or Newton pseudo-residuals','Learning rate','Additive score'],tasks:['task-binary','task-multiclass','task-regression','task-anomaly','task-scoring'],diagram:'boosting',tradeoff:'Excellent for tabular data and nonlinear crosses; awkward for end-to-end high-cardinality representation learning.'},
  {id:'arch-lambdamart',title:'LambdaMART',family:'Tree Models',desc:'Fits boosted trees to LambdaRank pseudo-gradients weighted by ranking-metric impact.',formula:'Fₘ(x)=Fₘ₋₁(x)+ηhₘ(x),  λᵢⱼ∝|ΔNDCGᵢⱼ|',example:'A pair whose swap changes NDCG by 0.20 receives four times the metric weight of a pair changing it by 0.05.',components:['Query groups','Lambda pseudo-gradients','Regression trees','NDCG weighting'],tasks:['ltr'],diagram:'boosting',tradeoff:'Powerful tabular ranker; does not naturally learn huge embeddings end-to-end.'},
  {id:'arch-dnn',title:'DNN / MLP',family:'Feed-Forward Models',desc:'Stacks affine layers and nonlinear activations to learn distributed nonlinear interactions.',formula:'hˡ=φ(Wˡhˡ⁻¹+bˡ)',example:'x=[2,−1], W=[[0.5,1],[−0.5,0.25]], b=[0,0.5] → Wx+b=[0,−0.75] → ReLU=[0,0].',components:['Dense layers','Activation functions','Optional normalization/dropout','Task head'],tasks:['task-binary','task-multiclass','task-multilabel','task-regression','task-anomaly','task-scoring'],diagram:'dnn',tradeoff:'Flexible and embedding-friendly, but needs substantial data and careful training.'},
  {id:'arch-wide-deep',title:'Wide & Deep',family:'Feed-Forward Models',desc:'Combines memorized linear feature crosses with a deep path that generalizes through embeddings.',formula:'ŷ=g(wwideᵀxwide+wdeepᵀhdeep+b)',example:'The wide path memorizes country×device while the deep path learns similarity across user and item embeddings; both logits are summed.',components:['Wide linear path','Manual crosses','Deep path','Joint output head'],tasks:['task-binary','task-regression','task-scoring'],diagram:'parallel',tradeoff:'Balances memorization and generalization, but requires maintaining explicit wide features.'},
  {id:'arch-dcn',title:'DCN / DCNv2',family:'Feed-Forward Models',desc:'Runs explicit bounded-degree cross layers beside a deep nonlinear path.',formula:'xˡ⁺¹=x⁰⊙(Wˡxˡ+bˡ)+xˡ',example:'For the original vector-parameterized DCN, x⁰=[2,3] and w=[0.5,−0.25] give x⁰ᵀw=0.25 and x¹=x⁰·0.25+x⁰=[2.5,3.75] before bias.',components:['Encoded feature vector','Cross network','Deep network','Concatenation','Task head'],tasks:['task-binary','task-regression','task-scoring'],diagram:'parallel',tradeoff:'Efficient explicit feature interactions for CTR/CVR, with more architectural choices than a plain DNN.'},
  {id:'arch-cnn',title:'Convolutional Neural Network',family:'Structured Encoders',desc:'Uses shared local kernels to extract spatial patterns and build hierarchical receptive fields.',formula:'yᵢⱼₖ=φ(ΣₐᵦcKₐᵦcₖXᵢ₊ₐ,ⱼ₊ᵦ,c+bₖ)',example:'A 3×3 kernel sliding over a 224×224 image reuses the same nine spatial weights at every valid location. Most libraries implement the displayed operation as cross-correlation without flipping K.',components:['Convolution kernels','Activation','Pooling/stride','Feature maps','Task head'],tasks:['task-multiclass','task-multilabel','task-embedding','task-detection','task-segmentation'],diagram:'cnn',tradeoff:'Strong spatial inductive bias and parameter sharing; locality can limit long-range interactions.'},
  {id:'arch-rnn',title:'RNN / LSTM',family:'Structured Encoders',desc:'Processes a sequence recurrently, carrying state from one position to the next.',formula:'Vanilla RNN: hₜ=φ(Wₓxₜ+Wₕhₜ₋₁+b)',example:'At step 3, the state h₃ is computed from current input x₃ and h₂, which already summarizes steps 1–2. An LSTM replaces this simple update with input, forget, output, and cell-state gates.',components:['Shared recurrent cell','Hidden state','LSTM/GRU gates when used','Sequence/task head'],tasks:['task-forecasting','task-generation','task-embedding'],diagram:'rnn',tradeoff:'Natural streaming state, but sequential computation is slower and long dependencies are difficult without gating.'},
  {id:'arch-transformer',title:'Transformer',family:'Structured Encoders',desc:'Uses content-dependent attention so every token can aggregate information from other tokens.',formula:'Attention(Q,K,V)=softmax(QKᵀ/√dₖ)V',example:'If one query has attention weights [0.7,0.2,0.1], its output is 0.7v₁+0.2v₂+0.1v₃.',components:['Token embeddings','Self-attention','Feed-forward block','Residual connections','Layer normalization'],tasks:['task-multiclass','task-multilabel','task-embedding','task-detection','task-segmentation','task-generation','task-forecasting'],diagram:'transformer',tradeoff:'Rich long-range interactions and parallel training; attention cost and serving latency can be high.'},
  {id:'arch-two-tower',title:'Two-Tower Model',family:'Retrieval Models',desc:'Encodes query/user and item independently, then compares their vectors with a simple similarity.',formula:'s(q,i)=fθ(q)ᵀgφ(i)',example:'u=[0.8,0.6], v=[0.7,0.5] → score=0.56+0.30=0.86.',components:['Query tower','Item tower','Shared vector dimension','Dot/cosine similarity','ANN index'],tasks:['task-embedding','task-retrieval'],diagram:'towers',tradeoff:'Enables precomputed item vectors and ANN retrieval, but cannot model rich cross-side interactions before scoring.'},
  {id:'arch-cross-encoder',title:'Cross-Encoder',family:'Retrieval Models',desc:'Jointly encodes a query and candidate so attention can model fine-grained pair interactions.',formula:'s(q,i)=wᵀh[CLS]([CLS;q;SEP;i;SEP])',example:'The token “python” in a query can attend directly to “programming language” in a document before the joint [CLS] representation is scored.',components:['Joint token sequence','Transformer','Joint [CLS] or pooled representation','Scoring head'],tasks:['ltr','task-multiclass'],diagram:'transformer',tradeoff:'High-quality interaction model for small candidate sets; too expensive to run over the full corpus.'},
  {id:'arch-mmoe',title:'Multi-gate Mixture of Experts',family:'Multi-Task Models',desc:'Learns shared experts while each task uses its own normalized gating weights and prediction tower.',formula:'gₖ(x)=softmax(Wgₖx),  hₖ=Σₑgₖₑ(x)fₑ(x)',example:'CTR gate weights [0.8,0.2] and CVR weights [0.3,0.7] reuse two experts differently for each task.',components:['Shared experts','Task-specific softmax gates','Task towers','Multiple weighted losses'],tasks:['task-multilabel','task-binary','task-regression','task-scoring'],diagram:'multitask',tradeoff:'Balances sharing and specialization, but can suffer expert collapse, negative transfer, or competing task gradients.'}
];

