function systemTable(headers,rows){return `<div class="table-wrap"><table class="comparison system-table"><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table></div>`}

const visualLegend=()=>`<div class="visual-key" aria-label="Diagram color legend"><span class="data">Input / data</span><span class="state">Store / state</span><span class="model">Learned model</span><span class="compute">Serving computation</span><span class="policy">Decision / policy</span></div>`;
const vNode=(kind,title,detail,extra='')=>`<div class="visual-node ${kind} ${extra}"><strong>${title}</strong>${detail?`<small>${detail}</small>`:''}</div>`;
const down=(label='')=>`<div class="visual-down"><b>↓</b>${label?`<span>${label}</span>`:''}</div>`;

function systemArchitecture(id){
  if(id==='next-video')return `<div class="system-model-diagram" role="img" aria-label="Two-tower next-video retrieval feeding a multi-stage ranking architecture">${visualLegend()}<div class="diagram-section retrieval-section"><span class="diagram-section-title">1 · RETRIEVAL · run two encoders in parallel</span><div class="tower-layout"><div class="tower-path">${vNode('data','User sequence','video IDs · watch time · recency')}${down()}${vNode('model','History Transformer','u = fθ(history, current video)')}</div><div class="merge-core">${vNode('compute','Similarity + ANN','uᵀv · retrieve 5K','hero-node')}<span>two towers meet here</span></div><div class="tower-path">${vNode('data','Video representation','ID · title · frames · audio')}${down()}${vNode('model','Item encoder','v = gφ(video)')}</div></div></div>${down('candidate IDs + source and retrieval features')}<div class="diagram-section ranking-section"><span class="diagram-section-title">2 · RANKING · spend more compute as the set shrinks</span><div class="rank-funnel">${vNode('compute','Pre-ranker','small GBDT / DNN · 5K → 500')}<b>→</b>${vNode('state','Feature hydration','fresh user × video features')}<b>→</b><div class="ranker-card">${vNode('model','DCNv2 / MMoE','cross branch + deep experts')}<div class="head-fan"><i>p(click)</i><i>E[watch]</i><i>p(satisfied)</i><i>p(dislike)</i></div></div><b>→</b>${vNode('compute','Utility','weighted multi-objective score')}</div></div>${down()}${vNode('policy','Constrained re-ranker','diversity · freshness · safety · creator caps → final 20','final-node')}</div>`;
  if(id==='ad-ctr')return `<div class="system-model-diagram" role="img" aria-label="Ad CTR architecture with inputs feeding parallel cross and deep networks, then multiple heads and an auction">${visualLegend()}<div class="input-fan"><span class="diagram-section-title">SPARSE + DENSE INPUTS</span><div>${vNode('data','User','IDs · interests · aggregates')}${vNode('data','Ad / campaign','ID · category · creative')}${vNode('data','Context','placement · device · time')}${vNode('data','Exposure history','affinity · frequency')}</div></div>${down('embed IDs · normalize dense values · concatenate x⁰')}<div class="diagram-section"><span class="diagram-section-title">DCNv2 · the same x⁰ enters two complementary branches</span><div class="fork-label">x⁰ <b>↙</b><b>↘</b></div><div class="parallel-model"><div>${vNode('model','Cross network','xˡ⁺¹ = x⁰⊙(Wˡxˡ+bˡ)+xˡ')}<small>explicit bounded-degree interactions</small></div><div>${vNode('model','Deep network','dense → activation → dense')}<small>implicit distributed interactions</small></div></div><div class="join-label"><b>↘</b><span>concatenate [xᴸ ; hᴹ]</span><b>↙</b></div><div class="head-fan wide"><i>CTR</i><i>CVR</i><i>quality</i><i>hide / report</i></div></div>${down('calibrate each probability by traffic segment')}<div class="decision-row">${vNode('state','Budget + bid','campaign state')}<b>+</b>${vNode('compute','Expected value','bid × p(action) × quality')}<b>→</b>${vNode('policy','Auction winner','serve one eligible ad','final-node')}</div></div>`;
  if(id==='visual-search')return `<div class="system-model-diagram" role="img" aria-label="Visual search architecture separating offline catalog indexing from the online query path">${visualLegend()}<div class="swimlane offline-swim"><span>OFFLINE · CATALOG PREPARATION</span><div class="lane-flow">${vNode('data','Catalog media','images · title · metadata')}<b>→</b>${vNode('model','Multimodal item encoder','v = gφ(image, text, category)')}<b>→</b>${vNode('state','Versioned vector index','HNSW / IVF-PQ')}</div></div><div class="index-drop"><span>published index</span><b>↓</b></div><div class="swimlane online-swim"><span>ONLINE · ONE QUERY</span><div class="search-topology"><div class="query-stack">${vNode('data','Uploaded image / crop','pixels + detected region')}${down()}${vNode('model','Query CNN / ViT','q = fθ(image)')}</div><div class="search-join">${vNode('compute','ANN similarity search','qᵀv · top 1K','hero-node')}<small>query meets precomputed catalog state</small></div><div class="search-tail">${vNode('policy','Availability filter','inventory · locale · policy')}<b>→</b>${vNode('model','Pair re-ranker','visual + text + category + price')}<b>→</b>${vNode('compute','Top 50','ranked results','final-node')}</div></div></div></div>`;
  return `<div class="system-model-diagram" role="img" aria-label="Multimodal content safety architecture with a cascade, policy heads, and three decision paths">${visualLegend()}<div class="cascade-note">${vNode('policy','Known-content rules','hashes · hard legal rules')}<span>resolved items exit early</span><b>↘ remaining content</b></div><div class="input-fan safety-inputs"><span class="diagram-section-title">MODALITY-SPECIFIC ENCODERS</span><div>${vNode('model','Text / OCR','Transformer')}${vNode('model','Images / frames','CNN or ViT')}${vNode('model','Audio / speech','audio + transcript')}${vNode('data','Account context','history + aggregates')}</div></div>${down('representations converge')}<div class="safety-core">${vNode('model','Cross-modal fusion','late fusion or attention')}<b>→</b>${vNode('model','Shared experts / MMoE','policy-specific gates')}<b>→</b><div class="head-fan wide"><i>adult</i><i>violence</i><i>hate</i><i>fraud</i></div></div>${down('calibrated score + severity enters the policy engine')}<div class="policy-split">${vNode('policy','Policy engine','versioned thresholds · region · severity','hero-node')}<div class="decision-arrows"><span>↙ low</span><span>↓ uncertain</span><span>↘ high</span></div><div class="decision-grid">${vNode('compute','Allow / monitor','retain audit trace')}${vNode('state','Human review','queue by uncertainty and harm')}${vNode('policy','Reduce / remove','escalate severe cases')}</div></div><p class="model-note">The spatial split is intentional: cheap rules and screens reduce load before expensive multimodal inference; uncertain decisions feed human labels back into training.</p></div>`
}

function systemInfrastructure(id){const d=systemInfrastructureData[id],shared={
  'next-video':[['state','Online feature store','recent history + counters'],['state','Caches + ANN indexes','candidate and embedding state'],['model','Model serving','pre-rank + heavy rank']],
  'ad-ctr':[['state','Online feature store','user/ad/context aggregates'],['state','Budget + pacing state','strongly consistent controls'],['model','Scorer + calibrator','versioned batch inference']],
  'visual-search':[['state','Object + metadata store','media, inventory, locale'],['state','ANN index replicas','encoder-compatible vectors'],['model','Encoder + re-ranker','GPU/CPU serving pool']],
  'content-safety':[['state','Context + evidence store','history, audit, appeals'],['state','Review queues','priority + SLA state'],['model','Cascade serving','fast screen + deep model']]
}[id];const online=d.online.map(([name,detail],i)=>vNode(i===0?'data':i===d.online.length-1?'policy':i===3?'state':'compute',name,detail,`infra-step s${i+1}`)).join('<b class="lane-arrow">→</b>');const offline=d.offline.map(([name,detail],i)=>vNode(i<3?'data':i===d.offline.length-2?'state':i===d.offline.length-1?'policy':'model',name,detail,`infra-step s${i+1}`)).join('<b class="lane-arrow">→</b>');return `<div class="infra-diagram" role="img" aria-label="${systemBlueprints[id].title} production topology with an online request lane, shared serving state, and an offline learning loop">${visualLegend()}<div class="infra-lane online"><span>ONLINE REQUEST PATH · synchronous deadline</span><div class="infra-track">${online}</div></div><div class="shared-services"><span>SHARED STATE & SERVING PLANE</span><div>${shared.map(x=>vNode(...x)).join('')}</div><small>These components sit between the online consumers above and the publishers below.</small></div><div class="infra-connectors"><span>telemetry + outcomes ↙</span><b>↕</b><span>↗ validated features · models · indexes</span></div><div class="infra-lane offline"><span>OFFLINE LEARNING & DEPLOYMENT LOOP · asynchronous</span><div class="infra-track">${offline}</div></div><div class="feedback-return"><b>↖</b><span>deployment changes the serving system; serving generates the next training data</span><b>↗</b></div></div>`}

function systemPage(id){const c=systemBlueprints[id],stageKind=(name,i)=>/eligibility|ingest|upload|logging/i.test(name)?'data':/auction|re-rank|action/i.test(name)?'policy':/scor|encode|rank/i.test(name)?'model':'compute';return `${pageHead('APPLIED SYSTEM',c.title,c.desc,'requirements,data,features,models,tradeoffs,feature stores,serving stack,monitoring')}${learningPath(id)}
  <section class="system-contract">${c.contract.map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</section>
  <div class="panel"><span class="eyebrow">END-TO-END ARCHITECTURE</span><h2>How scale and compute narrow through the system</h2><div class="system-pipeline" role="img" aria-label="${c.title} pipeline">${c.pipeline.map(([name,volume,latency,model],i)=>`<div class="system-stage ${stageKind(name,i)}"><b>${i+1}</b><strong>${name}</strong><span>${volume}</span><small>${latency} · ${model}</small></div>`).join('')}</div><p class="tiny">Volumes and latency budgets are illustrative interview-scale assumptions; state and adjust them when requirements differ.</p></div>
  <div class="panel"><span class="eyebrow">MODEL ARCHITECTURE</span><h2>What runs inside the stages</h2>${systemArchitecture(id)}</div>
  <div class="panel"><span class="eyebrow">PRODUCTION SYSTEM ARCHITECTURE</span><h2>Online serving and offline learning loop</h2>${systemInfrastructure(id)}</div>
  <div class="panel"><span class="eyebrow">SYSTEM COMPONENTS</span><h2>Stateful services, stores, deployment, and fallbacks</h2>${systemTable(['Component','Responsibility','Freshness / latency','Failure behavior'],systemInfrastructureData[id].components)}</div>
  <div class="panel"><span class="eyebrow">SYSTEM DESIGN TRADEOFFS</span><h2>Infrastructure choices to discuss in an interview</h2>${systemTable(['Decision','Choice A','Choice B','How to decide'],systemInfrastructureData[id].decisions)}</div>
  <div class="panel"><span class="eyebrow">DATA & LABELS</span><h2>One concrete training example</h2>${systemTable(['Field','Example value','Why it matters'],c.row)}<p class="callout"><strong>Point-in-time rule:</strong> features belong on the left side only if they were available when the prediction was made. Outcomes and post-event aggregates belong only in labels.</p></div>
  <div class="panel"><span class="eyebrow">FEATURE ENGINEERING</span><h2>Raw values become model tensors</h2>${systemTable(['Feature group','Raw example','Encoding','Illustrative shape'],c.features)}</div>
  <div class="panel"><span class="eyebrow">MODELING CHOICES</span><h2>Default choices, alternatives, and tradeoffs</h2>${systemTable(['Stage / decision','Practical default','Why choose it','Alternatives and tradeoff'],c.models)}</div>
  <div class="panel worked"><span class="eyebrow">WORKED EXAMPLE</span><h2>Trace one example through the main model</h2>${c.worked.map(([k,v])=>`<div class="worked-step"><strong>${k}</strong><span>${v}</span></div>`).join('')}</div>
  <div class="panel"><span class="eyebrow">TRAINING OBJECTIVES</span><h2>What each loss teaches</h2>${systemTable(['Objective','Formula / loss','Training signal','Important tradeoff'],c.objectives)}</div>
  <div class="panel"><span class="eyebrow">EVALUATION</span><h2>Match the metric to the layer</h2>${systemTable(['Layer','Metrics','Question answered'],c.metrics)}</div>
  <div class="two-col"><div class="panel"><span class="eyebrow">SERVING & MONITORING</span><h2>Production design</h2><ol class="system-list">${c.serving.map(x=>`<li>${x}</li>`).join('')}</ol></div><div class="panel"><span class="eyebrow">FAILURE MODES</span><h2>Detection and mitigation</h2>${c.failures.map(([risk,why,fix])=>`<div class="failure-row"><strong>${risk}</strong><span>${why}</span><small>${fix}</small></div>`).join('')}</div></div>
  <div class="panel"><h2>Concepts used here</h2>${conceptLinks(id==='visual-search'?['task-embedding','task-retrieval','arch-cnn','arch-two-tower','contrastive-loss','recall-at-k','ltr']:id==='next-video'?['task-retrieval','task-scoring','arch-two-tower','ltr','arch-dcn','arch-mmoe','ndcg','serving']:id==='ad-ctr'?['task-binary','task-scoring','arch-logistic','arch-gbdt','arch-dcn','arch-mmoe','bce','normalized-entropy']:['task-multilabel','arch-cnn','arch-transformer','arch-mmoe','bce','focal-loss','precision','recall'])}</div>`}

function applied(ids){return `<div class="panel"><span class="eyebrow">APPLIED IN</span><h2>See this concept inside a system</h2>${conceptLinks(ids)}</div>`}

const renderers={overview,formulation,'learning-sequence':learningSequence,tasks,features,embeddings,recommenders,ltr,math,architectures,activations,losses,optimization,evaluation,stages,retrieval,data,serving,study};
function render(){nav();const item=routeItem(state.route),parentTitle=routeParentTitle(state.route),concept=conceptCatalog.find(x=>x.id===state.route),task=taskCatalog.find(x=>x.id===state.route),architecture=architectureCatalog.find(x=>x.id===state.route);$('#breadcrumbs').textContent=parentTitle?`Atlas / ${parentTitle} / ${item.title}`:`Atlas / ${item?item.title:'Overview'}`;let body=concept?conceptPage(concept):task?taskPage(task):architecture?architecturePage(architecture):renderers[state.route]?renderers[state.route]():systems.some(x=>x.id===state.route)?systemPage(state.route):overview();if(state.pathContext&&state.route!==state.pathContext){const system=routeItem(state.pathContext);body=`<div class="path-context"><span><strong>${system.title} learning path</strong><small>Study this concept, mark it complete, then return to see your next step.</small></span><button class="ghost" data-route="${state.pathContext}" data-path="${state.pathContext}">Return to path →</button></div>${body}`}$('#content').innerHTML=body;$('#markComplete').style.display=state.route==='overview'?'none':'block';$('#markComplete').textContent=state.completed.has(state.route)?'Completed ✓':'Mark complete';wire();progress()}

function drawPlot(id,{xMin,xMax,yMin,yMax,series,xTicks,yTicks,xLabel,yLabel,markers=[],W=760,H=330}){const svg=$(`#${id}`);if(!svg)return;const m={l:58,r:22,t:18,b:48},pw=W-m.l-m.r,ph=H-m.t-m.b,sx=x=>m.l+(x-xMin)/(xMax-xMin)*pw,sy=y=>m.t+ph-(y-yMin)/(yMax-yMin)*ph;let out='';yTicks.forEach(y=>{out+=`<line class="plot-grid" x1="${m.l}" y1="${sy(y)}" x2="${W-m.r}" y2="${sy(y)}"/><text class="plot-label" x="${m.l-10}" y="${sy(y)+4}" text-anchor="end">${y}</text>`});xTicks.forEach(x=>{out+=`<line class="plot-grid" x1="${sx(x)}" y1="${m.t}" x2="${sx(x)}" y2="${H-m.b}"/><text class="plot-label" x="${sx(x)}" y="${H-m.b+20}" text-anchor="middle">${x}</text>`});markers.forEach(({x,label})=>{out+=`<line class="plot-marker" x1="${sx(x)}" y1="${m.t}" x2="${sx(x)}" y2="${H-m.b}"/><text class="plot-marker-label" x="${sx(x)+4}" y="${m.t+12}">${label}</text>`});out+=`<line class="plot-axis" x1="${m.l}" y1="${H-m.b}" x2="${W-m.r}" y2="${H-m.b}"/><line class="plot-axis" x1="${m.l}" y1="${m.t}" x2="${m.l}" y2="${H-m.b}"/><text class="plot-title-label" x="${m.l+pw/2}" y="${H-8}" text-anchor="middle">${xLabel}</text><text class="plot-title-label" transform="translate(15 ${m.t+ph/2}) rotate(-90)" text-anchor="middle">${yLabel}</text>`;series.forEach((s,j)=>{const pts=[];for(let n=0;n<=240;n++){const x=xMin+(xMax-xMin)*n/240,y=Math.max(yMin,Math.min(yMax,s.fn(x)));pts.push(`${n?'L':'M'}${sx(x).toFixed(2)},${sy(y).toFixed(2)}`)}out+=`<path class="plot-series plot-series-${j+1}" d="${pts.join(' ')}"/>`});svg.innerHTML=out}

function wire(){document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>go(x.dataset.route,x.dataset.path||null));
  if($('#activationPlot'))drawPlot('activationPlot',{xMin:-5,xMax:5,yMin:-1.5,yMax:5,series:[{fn:x=>Math.max(0,x)},{fn:x=>1/(1+Math.exp(-x))},{fn:x=>Math.tanh(x)}],xTicks:[-5,-2.5,0,2.5,5],yTicks:[-1,0,1,2,3,4,5],xLabel:'pre-activation z',yLabel:'output φ(z)'});
  if($('#lossPlot'))drawPlot('lossPlot',{xMin:.02,xMax:.98,yMin:0,yMax:4,series:[{fn:p=>-Math.log(p)},{fn:p=>-Math.log(1-p)}],xTicks:[.02,.25,.5,.75,.98],yTicks:[0,1,2,3,4],xLabel:'predicted probability p',yLabel:'BCE loss'});
  if($('#conceptPlot')){const c=conceptCatalog.find(x=>x.id===state.route),configs={sigmoid:{xMin:-6,xMax:6,yMin:0,yMax:1,series:[{fn:x=>1/(1+Math.exp(-x))}],xTicks:[-6,-3,0,3,6],yTicks:[0,.25,.5,.75,1],xLabel:'logit z',yLabel:'σ(z)'},relu:{xMin:-5,xMax:5,yMin:-1,yMax:5,series:[{fn:x=>Math.max(0,x)}],xTicks:[-5,-2.5,0,2.5,5],yTicks:[0,1,2,3,4,5],xLabel:'z',yLabel:'ReLU(z)'},tanh:{xMin:-5,xMax:5,yMin:-1.2,yMax:1.2,series:[{fn:x=>Math.tanh(x)}],xTicks:[-5,-2.5,0,2.5,5],yTicks:[-1,-.5,0,.5,1],xLabel:'z',yLabel:'tanh(z)'},softmax:{xMin:-5,xMax:5,yMin:0,yMax:1,series:[{fn:z=>Math.exp(z)/(Math.exp(z)+2)},{fn:z=>1/(Math.exp(z)+2)}],xTicks:[-5,-2.5,0,2.5,5],yTicks:[0,.25,.5,.75,1],xLabel:'class-1 logit z₁; z₂=z₃=0',yLabel:'softmax probability'},gelu:{xMin:-4,xMax:4,yMin:-1,yMax:4,series:[{fn:x=>.5*x*(1+Math.tanh(Math.sqrt(2/Math.PI)*(x+.044715*x*x*x)))}],xTicks:[-4,-2,0,2,4],yTicks:[-1,0,1,2,3,4],xLabel:'z',yLabel:'GELU(z)'},bce:{xMin:.02,xMax:.98,yMin:0,yMax:4,series:[{fn:p=>-Math.log(p)},{fn:p=>-Math.log(1-p)}],xTicks:[.02,.25,.5,.75,.98],yTicks:[0,1,2,3,4],xLabel:'predicted probability p',yLabel:'loss'},mse:{xMin:-4,xMax:4,yMin:0,yMax:16,series:[{fn:e=>e*e}],xTicks:[-4,-2,0,2,4],yTicks:[0,4,8,12,16],xLabel:'residual y−ŷ',yLabel:'squared loss'},mae:{xMin:-4,xMax:4,yMin:0,yMax:4,series:[{fn:e=>Math.abs(e)}],xTicks:[-4,-2,0,2,4],yTicks:[0,1,2,3,4],xLabel:'residual y−ŷ',yLabel:'absolute loss'},huber:{xMin:-4,xMax:4,yMin:0,yMax:4,series:[{fn:e=>Math.abs(e)<=1?.5*e*e:Math.abs(e)-.5}],xTicks:[-4,-2,0,2,4],yTicks:[0,1,2,3,4],xLabel:'residual y−ŷ',yLabel:'Huber loss δ=1'},focal:{xMin:.02,xMax:.98,yMin:0,yMax:4,series:[{fn:p=>-Math.log(p)},{fn:p=>-(1-p)*(1-p)*Math.log(p)}],xTicks:[.02,.25,.5,.75,.98],yTicks:[0,1,2,3,4],xLabel:'true-class probability pₜ',yLabel:'loss'}};if(c&&configs[c.chart])drawPlot('conceptPlot',configs[c.chart])}
  if($('#lossCurve')){const d=lossDiagnostics[state.route],base={xMin:d.x[0],xMax:d.x[1],xTicks:d.ticks,markers:d.markers||[],W:520,H:285};drawPlot('lossCurve',{...base,yMin:d.y[0],yMax:d.y[1],series:d.loss,yTicks:d.yt,xLabel:d.xLabel,yLabel:'loss'});drawPlot('lossGradient',{...base,yMin:d.gy[0],yMax:d.gy[1],series:d.grad,yTicks:d.gyt,xLabel:d.xLabel,yLabel:d.gLabel})}
  if($('#prob')){let label=1;const update=()=>{const p=+$('#prob').value/100,loss=-(label*Math.log(p)+(1-label)*Math.log(1-p));$('#probOut').textContent=p.toFixed(2);$('#lossOut').textContent=loss.toFixed(3);$('#lossMeter').style.width=Math.min(100,loss/4.61*100)+'%';const correct=(label===1&&p>=.5)||(label===0&&p<.5);$('#lossMessage').textContent=(correct?(Math.abs(p-label)<.2?'Confident and correct: small loss.':'Correct side, but uncertain.'):(Math.abs(p-label)>.8?'Confidently wrong: very large loss.':'Wrong side of the decision boundary.'));};$('#prob').oninput=update;$('#label0').onclick=()=>{label=0;$('#label0').classList.add('active');$('#label1').classList.remove('active');update()};$('#label1').onclick=()=>{label=1;$('#label1').classList.add('active');$('#label0').classList.remove('active');update()}}
  if($('#userDim')){const update=()=>{const a=+$('#userDim').value,b=+$('#itemDim').value,c=+$('#denseDim').value,t=a+b+c;$('#userDimOut').textContent=a;$('#itemDimOut').textContent=b;$('#denseDimOut').textContent=c;$('#totalDim').textContent=t;$('#shapeEquation').textContent=`${a} + ${b} + ${c} dimensions`;$('#shapeMeter').style.width=Math.min(100,t/424*100)+'%'};['#userDim','#itemDim','#denseDim'].forEach(s=>$(s).oninput=update)}
  if($('#archA')){$('#archB').selectedIndex=3;const update=()=>{const a=$('#archA').value,b=$('#archB').value,A=architectureData[a],B=architectureData[b];$('#archTable').innerHTML=`<table class="comparison"><tr><th>Dimension</th><th>${a}</th><th>${b}</th></tr>${[['Core formula','formula'],['Feature interactions','interaction'],['Best fit','best'],['Serving cost','cost'],['Main caution','risk']].map(r=>`<tr><td>${r[0]}</td><td>${A[r[1]]}</td><td>${B[r[1]]}</td></tr>`).join('')}</table>`};$('#archA').onchange=update;$('#archB').onchange=update;update()}
  if($('#activationZ')){const update=()=>{const z=+$('#activationZ').value/10,fn=$('#activationFn').value;let y,g,note;if(fn==='relu'){y=Math.max(0,z);g=z>0?1:0;note=z<0?'The negative ReLU branch passes neither value nor gradient.':'The positive ReLU branch is linear with gradient 1.'}else if(fn==='sigmoid'){y=1/(1+Math.exp(-z));g=y*(1-y);note='Sigmoid maps to (0,1), but its gradient shrinks near both extremes.'}else if(fn==='tanh'){y=Math.tanh(z);g=1-y*y;note='tanh is zero-centered but still saturates for large |z|.'}else{y=z>0?z:.01*z;g=z>0?1:.01;note='Leaky ReLU retains a small gradient on the negative branch.'}$('#activationZOut').textContent=z.toFixed(1);$('#activationOut').textContent=y.toFixed(3);$('#activationGrad').textContent=`local gradient = ${g.toFixed(3)}`;$('#activationNote').textContent=note};$('#activationZ').oninput=update;$('#activationFn').onchange=update;update()}
  if($('#recallCard')){let i=0,attempts=0,correct=0;const show=()=>{$('#recallTopic').textContent=recallCards[i].topic;$('#recallPosition').textContent=`${i+1} / ${recallCards.length}`;$('#recallQuestion').textContent=recallCards[i].q;$('#recallAnswer').innerHTML=`<span class="eyebrow">ANSWER</span><p>${recallCards[i].a}</p>`;$('#recallAnswer').classList.remove('shown');$('#revealRecall').classList.remove('hidden');$('#recallAgain').classList.add('hidden');$('#recallGood').classList.add('hidden')};const next=got=>{attempts++;if(got)correct++;$('#recallScore').textContent=`${correct} / ${attempts}`;i=(i+1)%recallCards.length;show()};$('#revealRecall').onclick=()=>{$('#recallAnswer').classList.add('shown');$('#revealRecall').classList.add('hidden');$('#recallAgain').classList.remove('hidden');$('#recallGood').classList.remove('hidden')};$('#recallAgain').onclick=()=>next(false);$('#recallGood').onclick=()=>next(true)}
  if($('#systemTabs')){const cfg={
    'next-video':['Expected long-term user value, approximated with watch time, satisfaction, and retention signals.','Impression → click/watch; include watch duration and satisfaction targets with explicit windows; preserve request/query groups for LTR.','User history, current video, creator/topic, context, freshness, plus text/image/audio/video encodings and user–video crosses.','Union collaborative candidates (MF/co-watch), content-based candidates, popular/fresh items, and two-tower retrieval → lightweight pre-ranker → pointwise multi-task DNN/DCN or pairwise/listwise LTR/LambdaMART ranker → optimization re-ranker.','Recall@K by candidate source; grouped NDCG/MRR for ranking; calibration for probabilistic heads; then watch time, satisfaction, retention, and diversity online.','Position bias, filter bubbles, autoplay confounding, cold start, stale embeddings, source collapse, query-group leakage, and short-term optimization.'],
    'ad-ctr':['Auction utility combines predicted action rate, advertiser value, quality, and policy.','Click within a window following an impression; conversions require delayed-label handling.','User/ad/context features plus explicit or learned user–ad crosses.','Logistic baseline → GBDT or DNN/DCNv2 with embeddings → calibration.','Normalized entropy, log loss, PR-AUC, calibration; revenue and UX guardrails online.','Extreme sparsity, selection bias, drift, campaign cold start, and calibration failures.'],
    'visual-search':['Retrieve visually and semantically relevant catalog items at low latency.','Positive image–item pairs from behavior or judgment, with mined hard negatives.','Pixels encoded by CNN/ViT plus catalog metadata and optional text embeddings.','Dual encoder → ANN index → metadata filter → multimodal re-ranker.','Recall@K, mAP/NDCG, human relevance, product engagement, and latency.','Duplicates, domain shift, stale catalog, and visual similarity without semantic relevance.'],
    'content-safety':['Minimize expected harm and review cost under asymmetric errors.','Policy judgments with adjudication; preserve uncertainty and policy version.','Multimodal content representations plus account and contextual signals.','Modality encoders → multi-task heads; cascades for recall then precision.','Precision/recall by severity, PR-AUC, queue load, and appeal reversals.','Policy drift, adversaries, reviewer disagreement, fairness, and rare positives.']
  }[state.route];const titles=['Objective & framing','Data and labels','Feature plan','Model plan','Evaluation plan','Failure modes'];const show=i=>{$('#systemDetail').innerHTML=`<span class="eyebrow">STEP ${i+1}</span><h2>${titles[i]}</h2><p>${cfg[i]}</p><p class="callout"><strong>Say this explicitly:</strong> ${i===0?'The model metric is a proxy; the online experiment validates product value.':i===1?'Every feature must be available at the exact prediction timestamp.':i===2?'Name the raw feature, its encoding, and its final tensor shape.':i===3?'Begin with a baseline, then justify added complexity from a concrete limitation.':i===4?'Match metrics to pipeline stage and include guardrails.':'Describe detection, mitigation, and the operational owner.'}</p>`;document.querySelectorAll('.tab').forEach((t,j)=>t.classList.toggle('active',i===j))};document.querySelectorAll('.tab').forEach((t,i)=>t.onclick=()=>show(i));show(0)}
}

function progress(){const trackable=new Set(['formulation','learning-sequence','study','tasks','ltr',...taxonomy.map(x=>x.id),...taxonomy.flatMap(x=>x.children),...taskCatalog.map(x=>x.id),...systems.map(x=>x.id)]),done=[...state.completed].filter(x=>trackable.has(x)).length,pct=Math.round(done/trackable.size*100);$('#progressText').textContent=pct+'%';$('#progressBar').style.width=pct+'%'}
$('#markComplete').onclick=()=>{state.completed.has(state.route)?state.completed.delete(state.route):state.completed.add(state.route);localStorage.setItem('atlas-completed',JSON.stringify([...state.completed]));render()};
$('#resetProgress').onclick=()=>{state.completed.clear();localStorage.removeItem('atlas-completed');render()};
$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');
$('#searchInput').oninput=e=>{const q=e.target.value.toLowerCase().trim(),pool=[...taxonomy.map(x=>({...x,tag:'FOUNDATION',desc:`Explore ${x.title.toLowerCase()}.`,time:`${x.children.length||1} topics`})),...foundations,...conceptCatalog.map(x=>({...x,tag:'CONCEPT',time:'Study'})),...taskCatalog.map(x=>({...x,tag:'TASK',time:'Task guide'})),...architectureCatalog.map(x=>({...x,tag:'ARCHITECTURE',time:x.family})),...specialRoutes.map(x=>({...x,tag:'START HERE',time:'Guide'})),...systems],seen=new Set(),items=pool.filter(x=>{if(seen.has(x.id))return false;seen.add(x.id);return (x.title+' '+(x.desc||'')).toLowerCase().includes(q)});if(!q){render();return}$('#content').innerHTML=`${pageHead('SEARCH',`Results for “${e.target.value}”`,`${items.length} matching topics`)}${items.length?cards(items):'<div class="empty">No matching concepts yet.</div>'}`;wire()};
function showPrompt(){const p=prompts[Math.floor(Math.random()*prompts.length)];$('#promptTitle').textContent=p.title;$('#promptBody').textContent=p.body;$('#promptRubric').innerHTML=p.rubric.map(x=>`<li>${x}</li>`).join('');$('#promptDialog').showModal()}
$('#randomPrompt').onclick=showPrompt;$('#nextPrompt').onclick=showPrompt;$('#closeDialog').onclick=()=>$('#promptDialog').close();
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'overview';render()});render();
